mapper.select:
select count(*) from gb_department_goods_stock_reduce as gbdssr


        and gbdssr.gb_dgsr_distributer_id = #{params.disId}


        and gbdssr.gb_dgsr_department_id = #{params.depId}


        and gbdssr.gb_dgsr_date = #{params.date}


        and gbdssr.gb_dgsr_date >= #{params.startDate}


        and gbdssr.gb_dgsr_date <= #{params.stopDate}


        and gbdssr.gb_dgsr_type = #{params.type}


        and gbdssr.gb_dgsr_type in

            #{typeItem}

select IFNULL(sum(gbdssr.gb_dgsr_subtotal), 0) from gb_department_goods_stock_reduce as gbdssr


        and gbdssr.gb_dgsr_distributer_id = #{params.disId}


        and gbdssr.gb_dgsr_department_id = #{params.depId}


        and gbdssr.gb_dgsr_date = #{params.date}


        and gbdssr.gb_dgsr_date >= #{params.startDate}


        and gbdssr.gb_dgsr_date <= #{params.stopDate}


        and gbdssr.gb_dgsr_type = #{params.type}


        and gbdssr.gb_dgsr_type in

            #{typeItem}

select IFNULL(ROUND(SUM(gdgsr.gb_dgsr_subtotal), 1), 0) from gb_department_goods_stock_reduce as gdgsr
left join gb_department as gd on gd.gb_department_id = gdgsr.gb_dgsr_department_id


        and gdgsr.gb_dgsr_type = #{params.type}


        and gdgsr.gb_dgsr_distributer_id = #{params.disId}


        and gd.gb_department_type = #{params.depType}


        and gdgsr.gb_dgsr_department_id = #{params.depId}


        and gdgsr.gb_dgsr_date >= #{params.startDate}


        and gdgsr.gb_dgsr_date <= #{params.stopDate}


        and gdgsr.gb_dgsr_stock_nx_supplier_id = #{params.supplierId}


        and gdgsr.gb_dgsr_stock_pur_user_id = #{params.purUserId}

select 
    IFNULL(ROUND(SUM(case when gb_dgsr_type = 1 then gb_dgsr_subtotal else 0 end), 1), 0) as produceTotal,
    IFNULL(ROUND(SUM(case when gb_dgsr_type = 2 then gb_dgsr_subtotal else 0 end), 1), 0) as wasteTotal,
    IFNULL(ROUND(SUM(case when gb_dgsr_type = 3 then gb_dgsr_subtotal else 0 end), 1), 0) as lossTotal,
    IFNULL(ROUND(SUM(case when gb_dgsr_type = 4 then gb_dgsr_subtotal else 0 end), 1), 0) as returnTotal
from gb_department_goods_stock_reduce


        and gb_dgsr_department_id = #{params.departmentId}


        and gb_dgsr_distributer_id = #{params.disId}


        and gb_dgsr_date >= #{params.startDate}


        and gb_dgsr_date <= #{params.stopDate}

SELECT
    gb_dgsr_date AS date,
    IFNULL(ROUND(SUM(gb_dgsr_subtotal), 1), 0) AS total
FROM gb_department_goods_stock_reduce
WHERE 1=1

    AND gb_dgsr_date >= #{params.startDate}


    AND gb_dgsr_date <= #{params.stopDate}


    AND gb_dgsr_distributer_id = #{params.disId}

GROUP BY gb_dgsr_date
ORDER BY gb_dgsr_date
